/**
 * Shared metadata helpers. NEXT_PUBLIC_SITE_URL (optional) sets absolute URLs for Open Graph,
 * the sitemap and robots; without it Next falls back to its default base URL.
 */
import type { Metadata } from "next";

export const SITE_NAME = "FlameSight";
export const SITE_TAGLINE = "Fire-safety insight from NASA microgravity research";
export const SITE_DESCRIPTION =
  "FlameSight turns NASA's microgravity combustion research into fire-safety insight for Moon and Mars habitats. v0.1, preliminary / unverified.";

/** Generated by app/opengraph-image.tsx. */
export const OG_IMAGE = {
  url: "/opengraph-image",
  width: 1200,
  height: 630,
  alt: `${SITE_NAME}: ${SITE_TAGLINE}. v0.1 preliminary.`,
} as const;

/** Parsed NEXT_PUBLIC_SITE_URL, or null when unset or invalid. */
export const SITE_URL: URL | null = (() => {
  const raw = process.env.NEXT_PUBLIC_SITE_URL;
  if (!raw) return null;
  try {
    return new URL(raw);
  } catch {
    return null;
  }
})();

/** Per-route title and description, mirrored into Open Graph and Twitter card tags. */
export function pageMetadata({
  title,
  description,
}: {
  title: string;
  description: string;
}): Metadata {
  // Page-level openGraph/twitter objects replace the root ones, so repeat the shared image and card.
  return {
    title,
    description,
    openGraph: { title: `${title} · ${SITE_NAME}`, description, images: [OG_IMAGE] },
    twitter: {
      card: "summary_large_image",
      title: `${title} · ${SITE_NAME}`,
      description,
      images: [OG_IMAGE.url],
    },
  };
}
